package za.ac.cput.domain; import jakarta.persistence.*; @Embeddable public class NextOfKin {private String firstName,lastName,phoneNumber,relationship; protected NextOfKin(){} private NextOfKin(Builder b){firstName=b.firstName;lastName=b.lastName;phoneNumber=b.phoneNumber;relationship=b.relationship;} public String getFirstName(){return firstName;} public String getLastName(){return lastName;} public String getPhoneNumber(){return phoneNumber;} public String getRelationship(){return relationship;} public static class Builder{private String firstName,lastName,phoneNumber,relationship; public Builder setFirstName(String v){firstName=v;return this;} public Builder setLastName(String v){lastName=v;return this;} public Builder setPhoneNumber(String v){phoneNumber=v;return this;} public Builder setRelationship(String v){relationship=v;return this;} public NextOfKin build(){return new NextOfKin(this);}}}